insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_music2_v1'
from (values
('117.209.c.1.A',3,'Two seventh graders listen to a live choir and then to a studio recording of the same song. Comparing them, they notice the live version has:','["natural room acoustics and audience energy", "no sound at all", "a different composer", "no melody"]'::jsonb,0,'Live and recorded versions differ in acoustics and atmosphere.','original'),
('117.209.c.1.A',3,'Using a music app to compare two exemplary performances of one piece helps students identify differences in:','["pencil size", "interpretation and tone", "paper type", "page count"]'::jsonb,1,'Comparing models shows interpretive choices.','original'),
('117.209.c.1.B',3,'A melody that moves by step stays close together in pitch. A melody that moves by leap has:','["no pitches", "no rhythm", "larger jumps between notes", "the same note repeated"]'::jsonb,2,'Leaps skip over notes.','original'),
('117.209.c.1.B',3,'The term for the speed of the beat in a piece is:','["timbre", "tonality", "texture", "tempo"]'::jsonb,3,'Tempo is the speed of the beat.','original'),
('117.209.c.1.C',3,'A dotted half note in 4/4 time receives:','["three beats", "four beats", "one and a half beats", "two beats"]'::jsonb,0,'A dot adds half the note''s value: 2 + 1 = 3.','original'),
('117.209.c.1.C',3,'Four sixteenth notes together last as long as one:','["half note", "quarter note", "eighth note", "whole note"]'::jsonb,1,'Four sixteenths equal a quarter.','original'),
('117.209.c.1.D',3,'A piece with a returning main theme alternating with contrasting sections (ABACA) is in:','["canon form", "ternary form", "rondo form", "binary form"]'::jsonb,2,'Rondo returns to the A theme.','original'),
('117.209.c.1.D',3,'A composer presents a tune and then changes it with new rhythm, key or ornament each time. This is:','["a fugue", "a march", "a rondo", "theme and variations"]'::jsonb,3,'Theme and variations changes a main idea.','original'),
('117.209.c.1.E',3,'Hearing protection matters for musicians because loud sound over time can:','["damage hearing", "build tempo", "fix rhythm", "improve pitch"]'::jsonb,0,'Protecting hearing is part of musical wellness.','original'),
('117.209.c.1.E',3,'A string player prevents hand strain by:','["ignoring pain", "taking short breaks and keeping the wrist relaxed", "playing without rest", "gripping tightly"]'::jsonb,1,'Relaxed technique prevents injury.','original'),
('117.209.c.2.A',3,'A fermata over a note tells the performer to:','["play it softer", "play it shorter", "hold the note longer than written", "skip it"]'::jsonb,2,'Fermata means hold.','original'),
('117.209.c.2.A',3,'A coda symbol marks:','["the key change", "the tempo", "the opening bars", "the ending section of a piece"]'::jsonb,3,'A coda is a concluding passage.','original'),
('117.209.c.2.B',3,'A student uses notation software to enter a four-measure tune in 2/4 meter. Each measure must contain:','["two quarter-note beats", "six quarter-note beats", "four quarter-note beats", "three quarter-note beats"]'::jsonb,0,'2/4 has two quarter beats.','original'),
('117.209.c.2.B',3,'To notate a soft dynamic at the start of a phrase, a student writes:','["fff", "p", "ff", "f"]'::jsonb,1,'Piano (p) means soft.','original'),
('117.209.c.2.C',3,'A student expands a simple two-measure rhythm into an eight-measure phrase using varied note values. This is creating an:','["blank score", "incomplete idea", "increasingly complex rhythmic phrase", "silent piece"]'::jsonb,2,'Complex phrases build on known rhythms.','original'),
('117.209.c.2.C',3,'Creating a melody that moves up and then returns downward uses:','["static pitch", "only silence", "tempo changes only", "melodic contour"]'::jsonb,3,'Contour describes the shape of a melody.','original'),
('117.209.c.2.D',3,'Using solfege syllables while looking at notation helps develop:','["inner hearing", "handwriting speed", "costume sense", "posture"]'::jsonb,0,'Solfege links notation and sound.','original'),
('117.209.c.2.D',3,'Conducting patterns with the hand while reading music is an example of a:','["printed test", "kinesthetic response", "spoken quiz", "lighting plan"]'::jsonb,1,'Movement connects to musical reading.','original'),
('117.209.c.2.E',3,'Polyphonic music contains:','["only one melody", "only harmony", "two or more independent melodic lines", "no rhythm"]'::jsonb,2,'Polyphonic texture has independent lines.','original'),
('117.209.c.2.E',3,'Homophonic music features:','["only silence", "only drums", "only unison", "a melody supported by chords"]'::jsonb,3,'Homophony is melody plus chords.','original'),
('117.209.c.3.A',3,'Alto flute players adjust to match the tone of the section. This shows they are demonstrating characteristic:','["instrumental timbre", "key", "tempo", "rest"]'::jsonb,0,'Matching timbre blends the section.','original'),
('117.209.c.3.A',3,'A choir with a warm, round vowel sound shows well-formed:','["meter", "vocal timbre", "notation", "form"]'::jsonb,1,'Vowel shape affects vocal timbre.','original'),
('117.209.c.3.B',3,'Correct embouchure on a brass instrument helps produce a:','["buzzing mess", "sharp whine only", "clear, focused tone", "silent note"]'::jsonb,2,'Embouchure affects tone.','original'),
('117.209.c.3.B',3,'A percussionist holds sticks with a relaxed grip to produce:','["tension", "no sound", "wild bouncing", "controlled, even strokes"]'::jsonb,3,'Relaxed grips allow control.','original'),
('117.209.c.3.C',3,'A violinist who plays in tune with the section while keeping steady beats is demonstrating independent:','["musical accuracy", "costume style", "ticket price", "stage lighting"]'::jsonb,0,'Intonation and rhythm are accuracy basics.','original'),
('117.209.c.3.C',3,'Performing with expression means playing with:','["random volume", "dynamics and phrasing", "hidden notes", "no change at all"]'::jsonb,1,'Expressive performance uses dynamics and phrasing.','original'),
('117.209.c.3.D',3,'A concert program with a Renaissance madrigal, a spiritual and a jazz tune represents various:','["fonts", "shoe sizes", "styles and periods", "paint colors"]'::jsonb,2,'Variety of styles shows a varied repertoire.','original'),
('117.209.c.3.D',3,'Choosing contrasting pieces for a recital helps display a performer''s:','["parking", "lunch", "bus ride", "range of skills"]'::jsonb,3,'Contrast shows versatility.','original'),
('117.209.c.3.E',3,'During sight-reading, a player keeps a steady tempo by:','["counting subdivisions silently", "guessing wildly", "pausing every measure", "stopping after mistakes"]'::jsonb,0,'Counting keeps the pulse steady.','original'),
('117.209.c.3.E',3,'Sight-reading in a new key, a student first notes the:','["composer''s nickname", "key signature", "bar number", "page margin"]'::jsonb,1,'Key signature tells which notes are altered.','original'),
('117.209.c.3.F',3,'A ritardando tells performers to:','["stop", "play louder", "gradually slow down", "gradually speed up"]'::jsonb,2,'Ritardando means slowing.','original'),
('117.209.c.3.F',3,'The bass clef is also called the:','["C clef", "D clef", "G clef", "F clef"]'::jsonb,3,'The bass clef marks the pitch F.','original'),
('117.209.c.3.G',3,'A student composes a two-part melody where the second phrase answers the first like a question and answer. This is:','["antecedent and consequent phrasing", "random notes", "a glissando", "a drone"]'::jsonb,0,'Question-and-answer phrases are common.','original'),
('117.209.c.3.G',4,'To build an increasingly complex melody, a composer might add:','["only silence", "sequence, repetition and contrast", "only one note", "no rhythm"]'::jsonb,1,'Developing material makes phrases more complex.','original'),
('117.209.c.4.A',3,'Performing ''The Star-Spangled Banner'' connects students to:','["Asian court music only", "Medieval chant only", "American heritage", "space music"]'::jsonb,2,'It is a national anthem of the United States.','original'),
('117.209.c.4.A',3,'Singing ''Texas, Our Texas'' represents:','["Canadian history", "Roman history", "Egyptian history", "Texas heritage"]'::jsonb,3,'It is the Texas state song.','original'),
('117.209.c.4.B',4,'Examining a Gregorian chant and a rock song reveals differences in:','["genre, style and period", "staff color", "page number", "clef size"]'::jsonb,0,'Different eras and genres have different features.','original'),
('117.209.c.4.B',4,'Listening to a Renaissance madrigal and a modern pop song, a student notes the madrigal''s use of:','["synthesizers", "unaccompanied voices in polyphony", "drum kit", "electric guitar"]'::jsonb,1,'Madrigals were usually a cappella and polyphonic.','original'),
('117.209.c.4.C',3,'Counting patterns and measures in a piece relate to:','["cooking only", "woodworking", "mathematics", "geography"]'::jsonb,2,'Rhythm and meter involve math.','original'),
('117.209.c.4.C',3,'Studying how sound is produced by vibrating strings links music to:','["law", "geology only", "spelling", "physics"]'::jsonb,3,'Vibrations explain sound.','original'),
('117.209.c.4.D',2,'A recording engineer works in a:','["music-related vocation", "hospital ward", "bank vault", "farm field"]'::jsonb,0,'Recording engineering is a music career.','original'),
('117.209.c.4.D',2,'Singing in a community chorus on weekends is an:','["legal case", "avocation", "diploma", "mandatory job"]'::jsonb,1,'An avocation is pursued for enjoyment.','original'),
('117.209.c.5.A',2,'An informed listener at a formal concert waits to applaud until:','["before the conductor enters", "the first note", "a piece or movement has ended appropriately", "the middle of a solo"]'::jsonb,2,'Applause timing shows etiquette.','original'),
('117.209.c.5.A',2,'A performer shows stage etiquette by:','["walking off", "ignoring applause", "turning away", "acknowledging the audience and the ensemble with a bow"]'::jsonb,3,'Bowing is a courteous gesture.','original'),
('117.209.c.5.B',3,'One criterion when evaluating a choral performance is:','["balance among voice parts", "number of programs printed", "coat check line", "stage color"]'::jsonb,0,'Balance is a musical criterion.','original'),
('117.209.c.5.B',3,'Applying criteria while listening means:','["guessing quickly", "using specific musical standards to judge", "ignoring details", "liking only favorites"]'::jsonb,1,'Criteria structure judgment.','original'),
('117.209.c.5.C',3,'A student sets a goal to improve her sight-reading by practicing a new line each day. This is a tool for:','["ignoring skills", "pausing growth", "personal artistic improvement", "forgetting notes"]'::jsonb,2,'Goals support improvement.','original'),
('117.209.c.5.C',3,'Self-evaluation tools include a rubric, a recording and a:','["podium light", "stage curtain", "tuning fork only", "practice journal"]'::jsonb,3,'Journals document progress.','original'),
('117.209.c.5.D',3,'To evaluate a personal performance, a student applies criteria such as:','["tone, rhythm accuracy and dynamics", "wardrobe cost", "seat number", "poster design"]'::jsonb,0,'Criteria are musical qualities.','original'),
('117.209.c.5.D',3,'After her solo, a student rates her intonation as strong but her rhythm as weak, using a rubric. She is:','["skipping a step", "applying criteria to her own performance", "ignoring the rubric", "avoiding feedback"]'::jsonb,1,'A rubric supports self-evaluation.','original'),
('117.209.c.5.E',4,'Comparing a school band''s performance to a professional model recording helps evaluate its:','["program length", "ticket revenue", "quality and effectiveness", "stage size"]'::jsonb,2,'Models guide evaluation.','original'),
('117.209.c.5.E',4,'A listener notes that the ensemble''s articulation was less crisp than the model. This is an evaluation based on:','["a coin flip", "personal luck", "the weather", "a comparison to an exemplar"]'::jsonb,3,'Comparing to exemplars supports evaluation.','original'),
('117.209.c.5.F',3,'Gently swaying to a slow, flowing melody shows an appropriate response to its:','["mood and phrasing", "price", "cover", "paper"]'::jsonb,0,'Responses should fit the music.','original'),
('117.209.c.5.F',3,'Showing an appropriate cognitive response to music includes:','["leaving the room", "describing what you hear using music vocabulary", "ignoring the music", "talking loudly"]'::jsonb,1,'Cognitive responses involve thinking about the music.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
